input.command:
for f in /app/varsea/*/*.bin; do echo "== $f"; od -An -v -t u1 "$f" | awk '
{ for (i=1;i<=NF;i++) b[n++] = $i }
function ord(c){ return index(" !\"#$%&\x27()*+,-./0123456789:;<=>?@ABCDEFGHIJKLMNOPQRSTUVWXYZ[\\]^_`abcdefghijklmnopqrstuvwxyz{|}~", c) - 1 }
END {
  split("PASSWORD=8XD", P1, ""); split("8XD", P2, "");
  test("PASSWORD=8XD", P1, 10); test("8XD", P2, 3);
}
function test(name, P, L,   K, j, ok) {
  K = b[0] xor P[1]; ok = 1;
  for (j=1; j<=L && j<n; j++) if (b[j] xor K != P[j+1]) ok = 0;
  printf "  prefix \"%s\" key=%d match=%d\n", name, K, ok;
}' ; done

input.content:
# Known-plaintext repeating-XOR recovery.
# Reads one file's bytes (od -An -v -t u1 output) per run, via -v fname.
# Plaintext A: "PASSWORD=8XD" + 17x[A-Z0-9] + "W54"  (32 bytes)
# Plaintext B: "8XD" + 17x[A-Z0-9] + "W54"           (23 bytes)
{ for (i = 1; i <= NF; i++) b[n++] = $i }
END {
  # --- plaintext A: PASSWORD=8XD ... W54
  split("PASSWORD=8XD", PA, "");
  split("W54", SA, "");
  for (o = 0; o + 32 <= n; o++) {
    for (L = 1; L <= 12; L++) {
      delete key; ok = 1;
      for (i = 0; i < L && i < 12; i++) {
        k = b[o+i+1] xor PA[i+1];
        if (k in key) { if (key[k_in] != 0) {} }
        if ((i) in key) { if (key[i] != k) { ok = 0; break } }
        key[i] = k; k_in = i;
      }
      if (!ok) continue;
      for (i = L; i < 12; i++) if (b[o+i+1] xor key[i % L] != PA[i+1]) { ok = 0; break }
      if (!ok) continue;
      for (i = 12; i < 29; i++) {
        c = b[o+i+1] xor key[i % L];
        if (!((c >= 45 && c <= 57) || (c >= 65 && c <= 90))) { ok = 0; break }
      }
      if (!ok) continue;
      for (i = 29; i < 32; i++) if (b[o+i+1] xor key[i % L] != SA[i-28]) { ok = 0; break }
      if (!ok) continue;
      pw = "";
      for (i = 9; i < 32; i++) pw = pw sprintf("%c", b[o+i+1] xor key[i % L]);
      printf "HIT-A file=%s off=%d L=%d key=%d pw=%s\n", fname, o, L, (L==1?key[0]:""), pw;
    }
  }
  # --- plaintext B: 8XD ... W54 (L <= 3)
  split("8XD", PB, "");
  for (o = 0; o + 23 <= n; o++) {
    for (L = 1; L <= 3; L++) {
      delete key; ok = 1;
      for (i = 0; i < L; i++) key[i] = b[o+i+1] xor PB[i+1];
      for (i = 3; i < 20; i++) {
        c = b[o+i+1] xor key[i % L];
        if (!((c >= 45 && c <= 57) || (c >= 65 && c <= 90))) { ok = 0; break }
      }
      if (!ok) continue;
      for (i = 20; i < 23; i++) if (b[o+i+1] xor key[i % L] != SA[i-19]) { ok = 0; break }
      if (!ok) continue;
      pw = "";
      for (i = 0; i < 23; i++) pw = pw sprintf("%c", b[o+i+1] xor key[i % L]);
      printf "HIT-B file=%s off=%d L=%d pw=%s\n", fname, o, L, pw;
    }
  }
}

