# More encodings: Caesar mod-256 (repeat key), ROT13 windows, stride stego, LSB stego.
{ for (i = 1; i <= NF; i++) b[n++] = $i }
function isok(c) { return (c >= 45 && c <= 57) || (c >= 65 && c <= 90) }
function rot13(c,  r) {
  if (c >= 65 && c <= 90) r = 65 + (c - 65 + 13) % 26;
  else if (c >= 97 && c <= 122) r = 97 + (c - 97 + 13) % 26;
  else r = c;
  return r;
}
function checkA(s, L) {
  # s = array of 32 decoded bytes (1-based), expect PASSWORD=8XD +17 ok+ W54
  split("PASSWORD=8XD", PA, ""); split("W54", SA, "");
  for (i = 1; i <= 12; i++) if (s[i] != PA[i]) return 0;
  for (i = 13; i <= 29; i++) if (!isok(s[i])) return 0;
  for (i = 30; i <= 32; i++) if (s[i] != SA[i-29]) return 0;
  pw = "";
  for (i = 10; i <= 32; i++) pw = pw sprintf("%c", s[i]);
  printf "HIT %s: pw=%s\n", L, pw;
  return 1;
}
END {
  split("PASSWORD=8XD", PA, ""); split("W54", SA, ""); split("8XD", PB, "");
  # Caesar mod-256, plaintext A, keylen 1..12
  for (o = 0; o + 32 <= n; o++) for (L = 1; L <= 12; L++) {
    ok = 1;
    for (i = 0; i < L; i++) K[i] = (b[o+i+1] - PA[i+1] + 256) % 256;
    for (i = 0; i < 32; i++) {
      c = (b[o+i+1] - K[i % L] + 256) % 256;
      s[i+1] = c;
    }
    if (checkA(s, "caesar off=" o " L=" L)) { found = 1 }
  }
  # ROT13 windows, plaintext A at 32 offsets
  for (o = 0; o + 32 <= n; o++) {
    for (i = 0; i < 32; i++) s[i+1] = rot13(b[o+i+1]);
    if (checkA(s, "rot13 off=" o)) found = 1;
  }
  # stride stego: 23 raw bytes every s-th
  for (s2 = 1; s2 * 22 < n; s2++) {
    for (i = 0; i < 23; i++) s[i+1] = b[i*s2+1];
    ok = 1;
    for (i = 1; i <= 3; i++) if (s[i] != PB[i]) ok = 0;
    if (ok) {
      for (i = 4; i <= 20; i++) if (!isok(s[i])) { ok = 0; break }
      if (ok) for (i = 21; i <= 23; i++) if (s[i] != SA[i-20]) ok = 0;
      if (ok) { pw = ""; for (i = 1; i <= 23; i++) pw = pw sprintf("%c", s[i]); printf "HIT stride=%d pw=%s\n", s2, pw }
    }
  }
  # LSB stego: first 184 / last 184 bytes -> 23 bits each
  for (which = 1; which <= 2; which++) {
    for (k = 0; k < 23; k++) {
      byte = (which == 1) ? b[k*8+1] : b[n - 184 + k*8 + 1];
      bits = 0;
      for (j = 0; j < 8; j++) bits = bits * 2 + (byte % 2);
      s[k+1] = bits;
    }
    ok = 1;
    for (i = 1; i <= 3; i++) if (s[i] != PB[i]) ok = 0;
    if (ok) {
      for (i = 4; i <= 20; i++) if (!isok(s[i])) { ok = 0; break }
      if (ok) for (i = 21; i <= 23; i++) if (s[i] != SA[i-20]) ok = 0;
      if (ok) { pw = ""; for (i = 1; i <= 23; i++) pw = pw sprintf("%c", s[i]); printf "HIT lsb%d pw=%s\n", which, pw }
    }
  }
}

