use strict; use warnings;
sub slurp { my $f=shift; open my $fh,'<:raw',$f or die "$f: $!"; local $/; my $d=<$fh>; close $fh; $d }
my %bin = (
 backup => slurp('/app/varsea/backup-5bbc53a0/1761108157319017506.bin'),
 cfg    => slurp('/app/varsea/cfg-9c5059a5/1761108157343064955.bin'),
 data   => slurp('/app/varsea/data-815023d4/1761108157243430303.bin'),
 logs   => slurp('/app/varsea/logs-6d85a702/1761108157287341389.bin'),
 tmp    => slurp('/app/varsea/tmp-96a1686e/1761108157187440736.bin'),
);
my $full = slurp('/app/varsea/disks/sub1/subA/subAlpha/ae3f4c.dat');
my $N = length $full;
print "dat size $N\n";

# ---- Test 1: dat[0..1023] ^ B[(i+ko)%5120] == 0 (image starts zeroed, key=bin tiled)
for my $n (sort keys %bin) {
  my $B = $bin{$n};
  for my $ko (0,1024,2048,3072,4096) {
    my $m = 0;
    for my $i (0..1023) { $m++ if ord(substr($full,$i,1)) == ord(substr($B,($i+$ko)%5120,1)); }
    print "T1 $n ko=$ko matches=$m/1024\n" if $m > 50;
  }
}
# ---- Test 2: residue constancy in dat mid window (1MB) for short repeating keys over zero plaintext
my $mid = substr($full, 1048576, 1048576);
my @d = unpack('C*', $mid);
my $M = 1048576;
for my $L (1..64) {
  my $good = 0;
  for my $r (0..$L-1) {
    my $first = $d[$r]; my $ok = 1;
    for (my $i=$r+$L; $i<$M; $i+=$L) { if ($d[$i] != $first) { $ok=0; last } }
    $good++ if $ok;
  }
  print "T2 L=$L const_residues=$good/$L\n" if $good*10 >= $L*9;
}
# ---- Test 3: pairwise XOR of bins: total zeros (random ~20)
